  final MagicClipTaskDatabase database;
  final DatabaseMagicClipTaskStore store;
  final MagicClipStateMachine machine;
  final MagicClipBackendConfig config;
  final Future<Result<List<MagicClipMedia>>> Function() loadMedia;

  Future<Result<List<MagicClipTask>>> tasks(int offset) async {
    final rows = await database.listMagicClipTasks(
      LocalMagicClipTaskScope(
        accountScope: config.accountScope,
        environment: config.environment,
        stableDeviceIdentity: config.stableDeviceIdentity,
      ),
      offset: offset,
    );
    if (rows case Failure<List<LocalMagicClipTaskRecord>>(:final error)) {
      return Result.failure(error);
    }
    final tasks = <MagicClipTask>[];
    for (final row in (rows as Success<List<LocalMagicClipTaskRecord>>).value) {
      final loaded = await store.load(
        MagicClipTaskKey(
          accountScope: config.accountScope,
          environment: config.environment,
          stableDeviceIdentity: config.stableDeviceIdentity,
          operationId: row.key.operationId,
        ),
      );
      if (loaded case Failure<MagicClipTask?>(:final error)) {
        return Result.failure(error);
      }
      final task = (loaded as Success<MagicClipTask?>).value;
      if (task != null) tasks.add(task);
    }
    return Result.success(tasks);
  }
}

