/// 仅分享已完整落盘的设备录音，避免把缺失文件伪装成系统分享成功。
Future<void> shareDeviceRecording(
  BuildContext context,
  DeviceRecordL10n l10n,
  DeviceMediaItem item,
) async {
  await shareRecordingFiles(context, l10n, [item.localPath]);
}

/// 分享一项或多项已经完整落盘的录音文件。
Future<void> shareRecordingFiles(
  BuildContext context,
  DeviceRecordL10n l10n,
  Iterable<String> paths,
) async {
  final candidates = paths
      .map((path) => path.trim())
      .where((path) => path.isNotEmpty)
      .toSet();

  try {
    final files = <XFile>[];
    for (final path in candidates) {
      final file = File(path);
      if (await file.exists() && await file.length() > 0) {
        files.add(XFile(file.path));
      }
    }
    if (!context.mounted) return;
    if (files.isEmpty) {
      AppToast.warning(context, l10n.recordAudioUnavailable);
      return;
    }
    final result = await SharePlus.instance.share(
      ShareParams(files: files, sharePositionOrigin: shareOriginFrom(context)),
    );
    if (context.mounted && result.status == ShareResultStatus.unavailable) {
      AppToast.error(context, l10n.recordOperationFailed);
    }
  } on Object catch (error) {
    debugPrint(
      '[DeviceRecordShare] failed count=${candidates.length} '
      'type=${error.runtimeType}',
    );
    if (context.mounted) {
      AppToast.error(context, l10n.recordOperationFailed);
    }
  }
}
