enum VideoStabilizationResult {
  supported,
  alreadyStabilized,
  unsupported,
  invalidInput,
}

enum VideoStabilizationFamily { phancy, genius }

/// Native routing selected from the glasses MVHD marker.
enum VideoStabilizationAlgorithm { phancy, genius }

final class VideoStabilizationRequest {
  const VideoStabilizationRequest({
    required this.operationId,
    required this.inputPath,
    required this.outputPath,
    required this.scope,
    required this.algorithm,
    this.deviceCode,
