  final VideoStabilizationScope scope;
  final VideoStabilizationAlgorithm algorithm;
  final String? deviceCode;

  /// Supplied by the platform toke<truncated omitted_approx_tokens="97" />;
}

VideoStabilizationAlgorithm? algorithmForSupport(
  VideoStabilizationSupport support,
) {
  switch (support.family) {
    case VideoStabilizationFamily.phancy:
      return VideoStabilizationAlgorithm.phancy;
    case VideoStabilizationFamily.genius:
      return VideoStabilizationAlgorithm.genius;
    case null:
      return null;
  }
}

/// Bridges the typed feature contract to Android/iOS native implementations.
